sysml:
// in Anforderungen
requirement <'R-008'> rampenfahrfaehigkeit {
    doc /* Das FTF befährt Rampen mit einer Steigung von höchstens 4 % mit voller Last. */
}

// in Verknuepfungen
satisfy Anforderungen::rampenfahrfaehigkeit by Physik::ftf.fahrwerk;

// in Anforderungen
requirement <'R-008'> schutzfeldHinten {
    doc /* Bei Rückwärtsfahrt wird das Schutzfeld hinter dem Fahrzeug überwacht. */
}

// in Physik::ftf
part <'P-009'> scannerHinten : Logik::Sicherheitslaserscanner;

// in Verknuepfungen
satisfy Anforderungen::schutzfeldHinten by Physik::ftf.scannerHinten;
